texts, bad = {}, []
for p in NEW:
    if os.path.exists(p):
        bad.append('already exists: ' + p)
for p, eds in EDITS.items():
    if not os.path.exists(p):
        bad.append('missing: ' + p); continue
    t = open(p, encoding='utf-8').read()
    texts[p] = t
    for old, new in eds:
        n = t.count(old)
        if n != 1:
            bad.append(p + ': ' + str(n) + ' match(es) for ' + repr(old[:60]))
if bad:
    sys.exit('Anchor check failed, nothing written:\n  ' + '\n  '.join(bad))

for p, body in NEW.items():
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, 'w', encoding='utf-8').write(body)
    print('  CREATED', p)
for p, eds in EDITS.items():
    t = texts[p]
    for old, new in eds:
        t = t.replace(old, new, 1)
    open(p, 'w', encoding='utf-8').write(t)
    print('  PATCHED', p, '(' + str(len(eds)) + ' edits)')
print('S195 applied. Next: git add -A && git commit -m "S195: audio tab" && git push')
